head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS20030";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — result

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods20030.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_if_6", fn: function(){ return ((((dma_pageContext.get("result") ?? "")) && typeof ((dma_pageContext.get("result") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("result") ?? "")).getRowCount() : ((((dma_pageContext.get("result") ?? "")) == null) ? 0 : (((dma_pageContext.get("result") ?? "")).length || 0))) > 0); } }, { id: "if_sprtRoomNo", fn: function(){ return (!(String(((dma_resultM.get("sprtRoomNo") ?? (() => { throw new Error("unresolved:" + "resultM.sprtRoomNo"); })())) == null ? '' : ((dma_resultM.get("sprtRoomNo") ?? (() => { throw new Error("unresolved:" + "resultM.sprtRoomNo"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20030.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fileDownRelLaw_onclick
 * @description 「전체보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fileDownRelLaw_onclick = function(e){
    try {
        scwin.fileDownRelLaw('' + dma_resultM.get("sprtRoomNo") + '','' + dma_resultM.get("attachSeq") + '','' + dma_resultM.get("attachFileNm") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20030.btn_fileDownRelLaw_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「레이어닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20030.btn_window_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fileDownRelLaw
 * @description file Down Rel Law 처리
 * @param {*} roomNo roomNo
 * @param {*} ipt_attachSeq ipt_attachSeq
 * @param {String} fileNm fileNm
 * @returns {void}
 * @hidden N
 */
scwin.fileDownRelLaw = function (roomNo, ipt_attachSeq, fileNm) {
    $('#ipt_sprtRoomNo', $('#attachForm')).val(roomNo);
    $('#ipt_attachSeq', $('#attachForm')).val(ipt_attachSeq);
    $('#ipt_attachFileNm', $('#attachForm')).val(fileNm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/ui/jsp/ULDODS20030.xml");  // TODO Stage2(V48): 대상 화면 ULDODS20030 이(가) ui-tobe 에 없음(미전환·공통 팝업) — 경로 확인
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile");
    $('#attachForm').submit();
};
